import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/util/Optional.h>
#include <cuda.h>
#include <cuda_runtime.h>
namespace {
constexpr int TILE_X = 16;
constexpr int TILE_Y = 16;
constexpr int OCB = 8;
constexpr int HALO_X = TILE_X + 2;
constexpr int HALO_Y = TILE_Y + 2;
constexpr int XSH_NUM = 3 * HALO_Y * HALO_X;
}
template <typename scalar_t>
__global__ void conv_transpose3d_forward_direct_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int Kd, int Kh, int Kw,
    int stride, int padding, int output_padding,
    int groups, bool has_bias) {
  const int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t total = (int64_t)N * Cout * Dout * Hout * Wout;
  if (idx >= total) return;
  int64_t t = idx;
  const int ox = (int)(t % Wout); t /= Wout;
  const int oy = (int)(t % Hout); t /= Hout;
  const int oz = (int)(t % Dout); t /= Dout;
  const int oc = (int)(t % Cout);  t /= Cout;
  const int n  = (int)t;
  const int out_per_group = Cout / groups;
  const int in_per_group = Cin / groups;
  const int g = oc / out_per_group;
  const int oc_local = oc - g * out_per_group;
  const int ic_begin = g * in_per_group;
  const int ic_end = ic_begin + in_per_group;
  scalar_t acc = has_bias ? bias[oc] : (scalar_t)0;
  const bool fast_k3_s1_p0 =
      (Kd == 3 && Kh == 3 && Kw == 3 && stride == 1 && padding == 0);
  if (fast_k3_s1_p0) {
    for (int ic = ic_begin; ic < ic_end; ++ic) {
      const scalar_t* xb = x + (((int64_t)n * Cin + ic) * Din * Hin * Win);
      const scalar_t* wb = weight + (((int64_t)ic * out_per_group + oc_local) * 27);
      #pragma unroll
      for (int kd = 0; kd < 3; ++kd) {
        const int iz = oz - kd;
        if (iz < 0 || iz >= Din) continue;
        #pragma unroll
        for (int kh = 0; kh < 3; ++kh) {
          const int iy = oy - kh;
          if (iy < 0 || iy >= Hin) continue;
          #pragma unroll
          for (int kw = 0; kw < 3; ++kw) {
            const int ix = ox - kw;
            if (ix < 0 || ix >= Win) continue;
            const scalar_t xv = xb[((int64_t)iz * Hin + iy) * Win + ix];
            const scalar_t wv = wb[(kd * 3 + kh) * 3 + kw];
            acc += xv * wv;
          }
        }
      }
    }
  } else {
    for (int ic = ic_begin; ic < ic_end; ++ic) {
      const scalar_t* xb = x + (((int64_t)n * Cin + ic) * Din * Hin * Win);
      const scalar_t* wb = weight + (((int64_t)ic * out_per_group + oc_local) * Kd * Kh * Kw);
      for (int kd = 0; kd < Kd; ++kd) {
        const int nz = oz + padding - kd;
        if (nz < 0 || (nz % stride) != 0) continue;
        const int iz = nz / stride;
        if (iz < 0 || iz >= Din) continue;
        for (int kh = 0; kh < Kh; ++kh) {
          const int ny = oy + padding - kh;
          if (ny < 0 || (ny % stride) != 0) continue;
          const int iy = ny / stride;
          if (iy < 0 || iy >= Hin) continue;
          for (int kw = 0; kw < Kw; ++kw) {
            const int nx = ox + padding - kw;
            if (nx < 0 || (nx % stride) != 0) continue;
            const int ix = nx / stride;
            if (ix < 0 || ix >= Win) continue;
            const scalar_t xv = xb[((int64_t)iz * Hin + iy) * Win + ix];
            const scalar_t wv = wb[((int64_t)kd * Kh + kh) * Kw + kw];
            acc += xv * wv;
          }
        }
      }
    }
  }
  out[idx] = acc;
}
template <typename scalar_t>
__global__ void conv_transpose3d_forward_tiled_k3s1p0_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    bool has_bias) {
  __shared__ scalar_t xs[3][HALO_Y][HALO_X];
  __shared__ scalar_t ws[OCB][27];
  __shared__ scalar_t bs[OCB];
  const int tx = threadIdx.x % TILE_X;
  const int ty = threadIdx.x / TILE_X;
  const int ox0 = blockIdx.x * TILE_X;
  const int oy_tiles = (Hout + TILE_Y - 1) / TILE_Y;
  const int oz = blockIdx.y / oy_tiles;
  const int oy0 = (blockIdx.y - oz * oy_tiles) * TILE_Y;
  const int oc_blocks = (Cout + OCB - 1) / OCB;
  const int n = blockIdx.z / oc_blocks;
  const int oc0 = (blockIdx.z - n * oc_blocks) * OCB;
  const int ox = ox0 + tx;
  const int oy = oy0 + ty;
  const bool valid_out = (ox < Wout) && (oy < Hout) && (oz < Dout);
  if (threadIdx.x < OCB) {
    const int oc = oc0 + threadIdx.x;
    bs[threadIdx.x] = (has_bias && oc < Cout) ? bias[oc] : (scalar_t)0;
  }
  __syncthreads();
  scalar_t acc[OCB];
  #pragma unroll
  for (int o = 0; o < OCB; ++o) acc[o] = bs[o];
  for (int ic = 0; ic < Cin; ++ic) {
    for (int idx = threadIdx.x; idx < XSH_NUM; idx += blockDim.x) {
      const int p = idx / (HALO_Y * HALO_X);
      const int r = idx - p * (HALO_Y * HALO_X);
      const int sy = r / HALO_X;
      const int sx = r - sy * HALO_X;
      const int iz = oz - 2 + p;
      const int iy = oy0 - 2 + sy;
      const int ix = ox0 - 2 + sx;
      scalar_t v = (scalar_t)0;
      if (iz >= 0 && iz < Din && iy >= 0 && iy < Hin && ix >= 0 && ix < Win) {
        v = x[(((int64_t)n * Cin + ic) * Din + iz) * Hin * Win + (int64_t)iy * Win + ix];
      }
      xs[p][sy][sx] = v;
    }
    for (int idx = threadIdx.x; idx < OCB * 27; idx += blockDim.x) {
      const int o = idx / 27;
      const int tap = idx - o * 27;
      const int oc = oc0 + o;
      ws[o][tap] = (oc < Cout) ? weight[(((int64_t)ic * Cout + oc) * 27) + tap] : (scalar_t)0;
    }
    __syncthreads();
    if (valid_out) {
      #pragma unroll
      for (int o = 0; o < OCB; ++o) {
        scalar_t a = acc[o];
        #pragma unroll
        for (int kd = 0; kd < 3; ++kd) {
          const int p = 2 - kd;
          #pragma unroll
          for (int kh = 0; kh < 3; ++kh) {
            const int sy = ty + 2 - kh;
            #pragma unroll
            for (int kw = 0; kw < 3; ++kw) {
              const int sx = tx + 2 - kw;
              a += xs[p][sy][sx] * ws[o][(kd * 3 + kh) * 3 + kw];
            }
          }
        }
        acc[o] = a;
      }
    }
    __syncthreads();
  }
  if (valid_out) {
    #pragma unroll
    for (int o = 0; o < OCB; ++o) {
      const int oc = oc0 + o;
      if (oc < Cout) {
        out[((((int64_t)n * Cout + oc) * Dout + oz) * Hout + oy) * Wout + ox] = acc[o];
      }
    }
  }
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.dim() == 5, "x must be NCDHW");
  TORCH_CHECK(weight.dim() == 5, "weight must be (Cin, Cout/groups, kD, kH, kW)");
  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  c10::optional<torch::Tensor> bc;
  if (bias.has_value()) {
    TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
    bc = bias->contiguous();
  }
  const int64_t N = xc.size(0);
  const int64_t Cin = xc.size(1);
  const int64_t Din = xc.size(2);
  const int64_t Hin = xc.size(3);
  const int64_t Win = xc.size(4);
  const int64_t wCin = wc.size(0);
  const int64_t out_per_group = wc.size(1);
  const int64_t Kd = wc.size(2);
  const int64_t Kh = wc.size(3);
  const int64_t Kw = wc.size(4);
  TORCH_CHECK(wCin == Cin, "weight/input channel mismatch");
  TORCH_CHECK(groups > 0, "groups must be positive");
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  TORCH_CHECK((Cin / groups) > 0, "invalid groups");
  const int64_t Cout = out_per_group * groups;
  if (bias.has_value()) {
    TORCH_CHECK(bc->numel() == Cout, "bias size mismatch");
  }
  const int64_t Dout = (Din - 1) * stride - 2 * padding + (Kd - 1) + output_padding + 1;
  const int64_t Hout = (Hin - 1) * stride - 2 * padding + (Kh - 1) + output_padding + 1;
  const int64_t Wout = (Win - 1) * stride - 2 * padding + (Kw - 1) + output_padding + 1;
  TORCH_CHECK(Dout >= 0 && Hout >= 0 && Wout >= 0, "invalid output size");
  auto out = torch::empty({N, Cout, Dout, Hout, Wout}, xc.options());
  const int64_t total = out.numel();
  if (total == 0) return out;
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  const bool fast_tiled =
      Kd == 3 && Kh == 3 && Kw == 3 && stride == 1 && padding == 0 &&
      output_padding == 0 && groups == 1;
  AT_DISPATCH_FLOATING_TYPES(xc.scalar_type(), "conv_transpose3d_forward", [&] {
    if (fast_tiled) {
      const dim3 block(TILE_X * TILE_Y);
      const int x_tiles = (int)((Wout + TILE_X - 1) / TILE_X);
      const int y_tiles = (int)((Hout + TILE_Y - 1) / TILE_Y);
      const int oc_blocks = (int)((Cout + OCB - 1) / OCB);
      const dim3 grid(
          (unsigned int)x_tiles,
          (unsigned int)(Dout * y_tiles),
          (unsigned int)(N * oc_blocks));
      conv_transpose3d_forward_tiled_k3s1p0_kernel<scalar_t><<<grid, block, 0, stream>>>(
          xc.data_ptr<scalar_t>(),
          wc.data_ptr<scalar_t>(),
          bc.has_value() ? bc->data_ptr<scalar_t>() : nullptr,
          out.data_ptr<scalar_t>(),
          (int)N, (int)Cin, (int)Cout,
          (int)Din, (int)Hin, (int)Win,
          (int)Dout, (int)Hout, (int)Wout,
          bc.has_value());
    } else {
      const int threads = 256;
      const int64_t blocks64 = (total + threads - 1) / threads;
      TORCH_CHECK(blocks64 <= 0x7fffffffLL, "too many blocks");
      const dim3 block(threads);
      const dim3 grid((unsigned int)blocks64);
      conv_transpose3d_forward_direct_kernel<scalar_t><<<grid, block, 0, stream>>>(
          xc.data_ptr<scalar_t>(),
          wc.data_ptr<scalar_t>(),
          bc.has_value() ? bc->data_ptr<scalar_t>() : nullptr,
          out.data_ptr<scalar_t>(),
          (int)N, (int)Cin, (int)Cout,
          (int)Din, (int)Hin, (int)Win,
          (int)Dout, (int)Hout, (int)Wout,
          (int)Kd, (int)Kh, (int)Kw,
          (int)stride, (int)padding, (int)output_padding,
          (int)groups, bc.has_value());
    }
  });
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
"""

_ext = load_inline(
    name="modelnew_conv_transpose3d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        if groups <= 0:
            raise ValueError("groups must be positive")
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("channels must be divisible by groups")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        k = kernel_size
        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels // groups, k, k, k))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size ** 3
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.conv_transpose3d_forward(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups,
        )

