import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/util/Optional.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void conv_transpose3d_forward_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int Kd, int Kh, int Kw,
    int stride, int padding, int output_padding,
    int groups, bool has_bias) {
  const int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t total = (int64_t)N * Cout * Dout * Hout * Wout;
  if (idx >= total) return;

  int64_t t = idx;
  const int ox = (int)(t % Wout); t /= Wout;
  const int oy = (int)(t % Hout); t /= Hout;
  const int oz = (int)(t % Dout); t /= Dout;
  const int oc = (int)(t % Cout);  t /= Cout;
  const int n  = (int)t;

  const int out_per_group = Cout / groups;
  const int in_per_group = Cin / groups;
  const int g = oc / out_per_group;
  const int oc_local = oc - g * out_per_group;
  const int ic_begin = g * in_per_group;
  const int ic_end = ic_begin + in_per_group;

  scalar_t acc = has_bias ? bias[oc] : (scalar_t)0;

  const bool fast_k3_s1_p0 =
      (Kd == 3 && Kh == 3 && Kw == 3 && stride == 1 && padding == 0);

  if (fast_k3_s1_p0) {
    // With stride=1/pad=0: out[o] = sum_k in[o-k] * w[k].
    for (int ic = ic_begin; ic < ic_end; ++ic) {
      const scalar_t* xb = x + (((int64_t)n * Cin + ic) * Din * Hin * Win);
      const scalar_t* wb = weight + (((int64_t)ic * out_per_group + oc_local) * 27);
      #pragma unroll
      for (int kd = 0; kd < 3; ++kd) {
        const int iz = oz - kd;
        if (iz < 0 || iz >= Din) continue;
        #pragma unroll
        for (int kh = 0; kh < 3; ++kh) {
          const int iy = oy - kh;
          if (iy < 0 || iy >= Hin) continue;
          #pragma unroll
          for (int kw = 0; kw < 3; ++kw) {
            const int ix = ox - kw;
            if (ix < 0 || ix >= Win) continue;
            const scalar_t xv = xb[((int64_t)iz * Hin + iy) * Win + ix];
            const scalar_t wv = wb[(kd * 3 + kh) * 3 + kw];
            acc += xv * wv;
          }
        }
      }
    }
  } else {
    for (int ic = ic_begin; ic < ic_end; ++ic) {
      const scalar_t* xb = x + (((int64_t)n * Cin + ic) * Din * Hin * Win);
      const scalar_t* wb = weight + (((int64_t)ic * out_per_group + oc_local) * Kd * Kh * Kw);
      for (int kd = 0; kd < Kd; ++kd) {
        const int nz = oz + padding - kd;
        if (nz < 0 || (nz % stride) != 0) continue;
        const int iz = nz / stride;
        if (iz < 0 || iz >= Din) continue;
        for (int kh = 0; kh < Kh; ++kh) {
          const int ny = oy + padding - kh;
          if (ny < 0 || (ny % stride) != 0) continue;
          const int iy = ny / stride;
          if (iy < 0 || iy >= Hin) continue;
          for (int kw = 0; kw < Kw; ++kw) {
            const int nx = ox + padding - kw;
            if (nx < 0 || (nx % stride) != 0) continue;
            const int ix = nx / stride;
            if (ix < 0 || ix >= Win) continue;
            const scalar_t xv = xb[((int64_t)iz * Hin + iy) * Win + ix];
            const scalar_t wv = wb[((int64_t)kd * Kh + kh) * Kw + kw];
            acc += xv * wv;
          }
        }
      }
    }
  }

  out[idx] = acc;
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.dim() == 5, "x must be NCDHW");
  TORCH_CHECK(weight.dim() == 5, "weight must be (Cin, Cout/groups, kD, kH, kW)");

  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  c10::optional<torch::Tensor> bc;
  if (bias.has_value()) {
    TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
    bc = bias->contiguous();
  }

  const int64_t N = xc.size(0);
  const int64_t Cin = xc.size(1);
  const int64_t Din = xc.size(2);
  const int64_t Hin = xc.size(3);
  const int64_t Win = xc.size(4);

  const int64_t wCin = wc.size(0);
  const int64_t out_per_group = wc.size(1);
  const int64_t Kd = wc.size(2);
  const int64_t Kh = wc.size(3);
  const int64_t Kw = wc.size(4);

  TORCH_CHECK(wCin == Cin, "weight/input channel mismatch");
  TORCH_CHECK(groups > 0, "groups must be positive");
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  TORCH_CHECK((Cin / groups) > 0, "invalid groups");

  const int64_t Cout = out_per_group * groups;
  if (bias.has_value()) {
    TORCH_CHECK(bc->numel() == Cout, "bias size mismatch");
  }

  const int64_t Dout = (Din - 1) * stride - 2 * padding + (Kd - 1) + output_padding + 1;
  const int64_t Hout = (Hin - 1) * stride - 2 * padding + (Kh - 1) + output_padding + 1;
  const int64_t Wout = (Win - 1) * stride - 2 * padding + (Kw - 1) + output_padding + 1;
  TORCH_CHECK(Dout >= 0 && Hout >= 0 && Wout >= 0, "invalid output size");

  auto out = torch::empty({N, Cout, Dout, Hout, Wout}, xc.options());
  const int64_t total = out.numel();
  if (total == 0) return out;

  const int threads = 256;
  const int64_t blocks64 = (total + threads - 1) / threads;
  TORCH_CHECK(blocks64 <= 0x7fffffffLL, "too many blocks");
  const dim3 block(threads);
  const dim3 grid((unsigned int)blocks64);
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();

  AT_DISPATCH_FLOATING_TYPES(xc.scalar_type(), "conv_transpose3d_forward", [&] {
    conv_transpose3d_forward_kernel<scalar_t><<<grid, block, 0, stream>>>(
        xc.data_ptr<scalar_t>(),
        wc.data_ptr<scalar_t>(),
        bc.has_value() ? bc->data_ptr<scalar_t>() : nullptr,
        out.data_ptr<scalar_t>(),
        (int)N, (int)Cin, (int)Cout,
        (int)Din, (int)Hin, (int)Win,
        (int)Dout, (int)Hout, (int)Wout,
        (int)Kd, (int)Kh, (int)Kw,
        (int)stride, (int)padding, (int)output_padding,
        (int)groups, bc.has_value());
  });

  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
"""

_ext = load_inline(
