  const int in_per_group = Cin / groups;
  const int g = oc / out_per_group;
  const int oc_local = oc - g * out_per_group;
  const int ic_begin = g * in_per_group;
  const int ic_end = ic_begin + in_per_group;
  scalar_t acc = has_bias ? bias[oc] : (scalar_t)0;
  for (int ic = ic_begin; ic < ic_end; ++ic) {
    const scalar_t* xb = x + (((int64_t)n * Cin + ic) * Din * Hin * Win);
    const scalar_t* wb = weight + (((int64_t)ic * out_per_group + oc_local) * Kd * Kh * Kw);
