// Structural rewrite: implicit-GEMM tiling for the benchmarked fast path.
// For one batch, C[oc, p] = sum_{ic,k} W[oc, ic, k] * Xcol[ic, k, p].
// The CTA stages K-tiles of W and im2col-generated X in shared memory and
uses 16x16 threads with 3x4 register blocking.
template <typename scalar_t>
__global__ void conv_transpose3d_implicit_gemm_k3s1p0_c48(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int N, int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    bool has_bias) {
  constexpr int C = 48;
  constexpr int KT = 32;
  constexpr int NT = 64;
  constexpr int THREADS = 256;
  extern __shared__ __align__(16) char smem_raw[];
  scalar_t* smA = reinterpret_cast<scalar_t*>(smem_raw);
  scalar_t* smB = smA + KT * C;
  const int n = blockIdx.z;
  const int P = Dout * Hout * Wout;
  const int col0 = blockIdx.y * NT;
  const int tid = threadIdx.x;
  const int K = C * 27;
  const int tx = tid & 15;
  const int ty = tid >> 4;
  const int oc0 = ty * 3;
  const int c0 = tx * 4;
  scalar_t acc[3][4];
  #pragma unroll
  for (int r = 0; r < 3; ++r) {
    #pragma unroll
    for (int c = 0; c < 4; ++c) acc[r][c] = (scalar_t)0;
  }
  const int64_t x_batch = (int64_t)n * C * Din * Hin * Win;
  const int64_t out_batch = (int64_t)n * C * P;
  for (int k0 = 0; k0 < K; k0 += KT) {
    __syncthreads();
    for (int i = tid; i < KT * C; i += THREADS) {
      const int kt = i / C;
      const int oc = i - kt * C;
      const int kg = k0 + kt;
      scalar_t v = (scalar_t)0;
      if (kg < K) {
        const int ic = kg / 27;
        const int kk = kg - ic * 27;
        v = weight[((int64_t)ic * C + oc) * 27 + kk];
      }
      smA[kt * C + oc] = v;
    }
    for (int i = tid; i < KT * NT; i += THREADS) {
      const int kt = i / NT;
      const int c = i - kt * NT;
      const int kg = k0 + kt;
      const int p = col0 + c;
      scalar_t v = (scalar_t)0;
      if (kg < K && p < P) {
        const int ic = kg / 27;
        int kk = kg - ic * 27;
        const int kd = kk / 9;
        kk -= kd * 9;
        const int kh = kk / 3;
        const int kw = kk - kh * 3;
        int q = p;
        const int ox = q % Wout; q /= Wout;
        const int oy = q % Hout; q /= Hout;
        const int oz = q;
        const int ix = ox - kw;
        const int iy = oy - kh;
        const int iz = oz - kd;
        if (ix >= 0 && ix < Win && iy >= 0 && iy < Hin && iz >= 0 && iz < Din) {
          v = x[x_batch + ((int64_t)ic * Din * Hin * Win) + ((int64_t)iz * Hin + iy) * Win + ix];
        }
      }
      smB[kt * NT + c] = v;
    }
    __syncthreads();
    #pragma unroll
    for (int kt = 0; kt < KT; ++kt) {
      scalar_t a[3];
      scalar_t b[4];
      #pragma unroll
      for (int r = 0; r < 3; ++r) a[r] = smA[kt * C + oc0 + r];
      #pragma unroll
      for (int c = 0; c < 4; ++c) b[c] = smB[kt * NT + c0 + c];
      #pragma unroll
      for (int r = 0; r < 3; ++r) {
        #pragma unroll
        for (int c = 0; c < 4; ++c) acc[r][c] += a[r] * b[c];
      }
    }
  }
  #pragma unroll
  for (int r = 0; r < 3; ++r) {
    const int oc = oc0 + r;
    const scalar_t bv = has_bias ? bias[oc] : (scalar_t)0;
    #pragma unroll
    for (int c = 0; c < 4; ++c) {
      const int p = col0 + c0 + c;
      if (p < P) out[out_batch + (int64_t)oc * P + p] = acc[r][c] + bv;
    }
  }
}
torch::Tensor conv_transpose3d_forward(
